// Oversized source payloads cannot fit within D1's 2 MB per-row limit.
export const churchEnrichmentPayloadChunks = sqliteTable("church_enrichment_payload_chunks", {
  enrichmentId: text("enrichment_id").notNull().references(() => churchEnrichments.id, { onDelete: "cascade" }),
  field: text("field").notNull(),
  part: integer("part").notNull(),
  value: text("value").notNull(),
}, (table) => ({ pk: primaryKey({ columns: [table.enrichmentId, table.field, table.part] }) }));
